def mc(id, difficulty, prompt, options, answer, why, display="prose", snippet=None):
    d = dict(id=id, topic="prompt", difficulty=difficulty, prompt=prompt, options=options, answer=answer, why=why, display=display)
    if snippet: d["snippet"] = snippet
    return d

def wr(id, difficulty, prompt, model, rubric):
    return dict(id=id, topic="prompt", type="written", difficulty=difficulty, prompt=prompt, model=model,
                rubric=[dict(point=p, keywords=k) for p, k in rubric])

